                    compNodeAtRoot[root] = ++componentCount;
                }

                int compNode = n + compNodeAtRoot[root];

                addEdge(v, compNode, p);
                addEdge(compNode, v, 0);
            }
        }

        int totalNodes = n + componentCount;
        long INF = Long.MAX_VALUE / 4;

        long[] dist = new long[totalNodes + 1];
        Arrays.fill(dist, INF);

        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[start] = 0;
        pq.add(new State(start, 0));

