                int v = to[e];
                long nd = cur.dist + weight[e];

                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.add(new State(v, nd));
                }
            }
        }

        if (dist[target] >= INF) {
            System.out.println(-1);
        } else {
            System.out.println(dist[target]);
        }
